\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Shows the combined duration of all regions without double-counting overlaps.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
